#pragma warning disable CA1725
using Microsoft.EntityFrameworkCore;using WhatsBiz.Application.Common.Interfaces;using WhatsBiz.Domain.Warehouses;
namespace WhatsBiz.Infrastructure.Persistence;
public sealed class WarehouseRepository(ApplicationDbContext db):IWarehouseRepository{public async Task<(IReadOnlyCollection<Warehouse>,int)> Search(string? search,bool? active,Guid? typeId,string sort,bool descending,int page,int size,CancellationToken token){var q=db.Warehouses.AsNoTracking().Include(x=>x.WarehouseType).Where(x=>!x.IsDeleted);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.WarehouseCode.Contains(search)||x.WarehouseName.Contains(search)||(x.ManagerName!=null&&x.ManagerName.Contains(search)));if(active.HasValue)q=q.Where(x=>x.IsActive==active);if(typeId.HasValue)q=q.Where(x=>x.WarehouseTypeId==typeId);q=(sort.ToLowerInvariant(),descending) switch{("warehousecode",false)=>q.OrderBy(x=>x.WarehouseCode),("warehousecode",true)=>q.OrderByDescending(x=>x.WarehouseCode),("capacity",false)=>q.OrderBy(x=>x.Capacity),("capacity",true)=>q.OrderByDescending(x=>x.Capacity),(_,true)=>q.OrderByDescending(x=>x.WarehouseName),_=>q.OrderBy(x=>x.WarehouseName)};var count=await q.CountAsync(token);return(await q.Skip((Math.Max(page,1)-1)*Math.Clamp(size,1,200)).Take(Math.Clamp(size,1,200)).ToArrayAsync(token),count);}public Task<Warehouse?> GetById(Guid id,bool tracking,CancellationToken token){var q=db.Warehouses.Include(x=>x.WarehouseType).Include(x=>x.Address).Include(x=>x.Contacts).Include(x=>x.Zones).ThenInclude(x=>x.Bins).Where(x=>!x.IsDeleted);if(!tracking)q=q.AsNoTracking();return q.SingleOrDefaultAsync(x=>x.WarehouseId==id,token);}public Task<bool> Duplicate(string code,string name,Guid? exclude,CancellationToken token)=>db.Warehouses.AnyAsync(x=>!x.IsDeleted&&(!exclude.HasValue||x.WarehouseId!=exclude)&&(x.WarehouseCode==code.Trim()||x.WarehouseName==name.Trim()),token);public async Task<IReadOnlyCollection<WarehouseType>> Types(CancellationToken token)=>await db.WarehouseTypes.AsNoTracking().OrderBy(x=>x.TypeName).ToArrayAsync(token);public Task<WarehouseType?> GetTypeById(Guid id,bool tracking,CancellationToken token){var q=db.WarehouseTypes.AsQueryable();if(!tracking)q=q.AsNoTracking();return q.SingleOrDefaultAsync(x=>x.WarehouseTypeId==id,token);}public Task<bool> DuplicateType(string code,string name,Guid? exclude,CancellationToken token)=>db.WarehouseTypes.AnyAsync(x=>(!exclude.HasValue||x.WarehouseTypeId!=exclude)&&(x.TypeCode==code.Trim()||x.TypeName==name.Trim()),token);public void Add(Warehouse warehouse)=>db.Warehouses.Add(warehouse);public void Add(WarehouseType type)=>db.WarehouseTypes.Add(type);public void RemoveChildren(Warehouse warehouse){if(warehouse.Address is not null)db.WarehouseAddresses.Remove(warehouse.Address);db.WarehouseContacts.RemoveRange(warehouse.Contacts);foreach(var zone in warehouse.Zones)db.WarehouseBins.RemoveRange(zone.Bins);db.WarehouseZones.RemoveRange(warehouse.Zones);warehouse.Address=null;warehouse.Contacts=[];warehouse.Zones=[];}public void Remove(WarehouseType type)=>db.WarehouseTypes.Remove(type);public Task Save(CancellationToken token)=>db.SaveChangesAsync(token);}
